import { decodeDomainSet, type EncodedDomainSet } from '../lib/domain-set';
import encoded from './tranco-top100k.json';

/**
 * Bundled Tranco top-100k registrable domains (generated by `npm run build:data`).
 * Exact 32-bit hash set: no false negatives, false-positive rate ≈ 2.3e-5.
 */
export const trancoTop100k = decodeDomainSet(encoded as EncodedDomainSet);

/** True when the registrable domain is in the bundled Tranco top 100k. */
export function has(domain: string): boolean {
  return trancoTop100k.has(domain);
}
